INSERT INTO collection_pages VALUES('f463e5b169c62664286beda60efc346880f60708d9c9374ab78b2b78fa659307','e24a35035686bfe028032b0ca055f736c3528cf39d651dc382f665284b95478c','{"hasNext":false,"items":[{"author":{"account":{"login":"chishiki37","providerType":"User"},"email":"chishiki37@users.noreply.github.com","name":"chishiki37"},"authoredDate":"2026-09-07T01:48:07Z","committedDate":"2026-09-07T01:48:07Z","committer":{"account":{"login":"chishiki37","providerType":"User"},"email":"chishiki37@users.noreply.github.com","name":"chishiki37"},"observedAt":"2026-10-09T00:33:27.830Z","repositoryId":1359645866,"sha":"5e05b8cf57c83b25ea45af4aca5bfc08dccb6b0a"}],"observedAt":"2026-10-09T00:33:27.830Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/260160803?v=4","events_url":"https://api.github.com/users/chishiki37/events{/privacy}","followers_url":"https://api.github.com/users/chishiki37/followers","following_url":"https://api.github.com/users/chishiki37/following{/other_user}","gists_url":"https://api.github.com/users/chishiki37/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/chishiki37","id":260160803,"login":"chishiki37","node_id":"U_kgDOD4G9Iw","organizations_url":"https://api.github.com/users/chishiki37/orgs","received_events_url":"https://api.github.com/users/chishiki37/received_events","repos_url":"https://api.github.com/users/chishiki37/repos","site_admin":false,"starred_url":"https://api.github.com/users/chishiki37/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/chishiki37/subscriptions","type":"User","url":"https://api.github.com/users/chishiki37","user_view_type":"public"},"comments_url":"https://api.github.com/repos/chishiki37/qwen3.8-flash-next-single-spark-miaai-verification/commits/5e05b8cf57c83b25ea45af4aca5bfc08dccb6b0a/comments","commit":{"author":{"date":"2026-09-07T01:48:07Z","email":"chishiki37@users.noreply.github.com","name":"chishiki37"},"comment_count":0,"committer":{"date":"2026-09-07T01:48:07Z","email":"chishiki37@users.noreply.github.com","name":"chishiki37"},"message":"MiaAI-Lab single-Spark Qwen3.8-Flash-Next recipe verification\n\nDeployed their turnkey recipe unmodified on edgexpert-3b24 (GB10):\n99 GB Mia-AiLab NVFP4 checkpoint + their vLLM image, shipped .env and\ntheir Sep-6 sweep config (two-line delta: YARN=1, MAX_NUM_SEQS=8).\n\nMeasured (HTTP battery, prose 256 tok, temp 0, median of 3):\n- shipped:  C1 34.3 / C4 100.7 / C8 145.3 tok/s\n- tuned:    C1 35.4 / C4 101.2 / C8 141.8 tok/s\nvs claims 48.7 / 113.7 / 162.9 (engine-side, sparkDash, their host):\nC4/C8 reproduce ~87-89%, C1 70-76%.\n\nEngine-side decomposition with their exact /metrics methodology:\nstep rate 72-73 ms vs 61.5 (-15..-17%, host-side) x MTP acceptance\n2.48 prose / 2.67 code vs 3.00 (-11..-17%, content regime); product\nequals the observed C1 ratio. Sweep config worth ~nothing on our box.\n\nDisclosure: the Sep-6 ''code'' probe was a silent sed no-op (prompt\nspanned two physical lines) - both Sep-6 runs were prose. Superseded\nby a parameterized x5-per-regime re-run on Sep-7; originals preserved\nwith the mislabel documented (report section 4).\n\n8h+ stable under their memwatch watchdog at ~16 GB host headroom.\nSecret-scanned; vendor claims quoted with commit + license attribution.","tree":{"sha":"18e20ad9755385b4abd3a66782e4607e7cb63460","url":"https://api.github.com/repos/chishiki37/qwen3.8-flash-next-single-spark-miaai-verification/git/trees/18e20ad9755385b4abd3a66782e4607e7cb63460"},"url":"https://api.github.com/repos/chishiki37/qwen3.8-flash-next-single-spark-miaai-verification/git/commits/5e05b8cf57c83b25ea45af4aca5bfc08dccb6b0a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/260160803?v=4","events_url":"https://api.github.com/users/chishiki37/events{/privacy}","followers_url":"https://api.github.com/users/chishiki37/followers","following_url":"https://api.github.com/users/chishiki37/following{/other_user}","gists_url":"https://api.github.com/users/chishiki37/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/chishiki37","id":260160803,"login":"chishiki37","node_id":"U_kgDOD4G9Iw","organizations_url":"https://api.github.com/users/chishiki37/orgs","received_events_url":"https://api.github.com/users/chishiki37/received_events","repos_url":"https://api.github.com/users/chishiki37/repos","site_admin":false,"starred_url":"https://api.github.com/users/chishiki37/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/chishiki37/subscriptions","type":"User","url":"https://api.github.com/users/chishiki37","user_view_type":"public"},"html_url":"https://github.com/chishiki37/qwen3.8-flash-next-single-spark-miaai-verification/commit/5e05b8cf57c83b25ea45af4aca5bfc08dccb6b0a","node_id":"C_kwDOUQqMqtoAKDVlMDViOGNmNTdjODNiMjVlYTQ1YWY0YWNhNWJmYzA4ZGNjYjZiMGE","parents":[],"sha":"5e05b8cf57c83b25ea45af4aca5bfc08dccb6b0a","url":"https://api.github.com/repos/chishiki37/qwen3.8-flash-next-single-spark-miaai-verification/commits/5e05b8cf57c83b25ea45af4aca5bfc08dccb6b0a"}],"requestUrl":"https://api.github.com/repos/chishiki37/qwen3.8-flash-next-single-spark-miaai-verification/commits?per_page=100&page=1&sha=5e05b8cf57c83b25ea45af4aca5bfc08dccb6b0a&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A21%3A58.044Z"}');
