INSERT INTO collection_pages VALUES('d15bae8a509c3d7a01634a3692c96af2d9c3f70e3627c92feedd2c660bda282d','12e3f051b91a846171098d18bf30b9fba858e7ef9941005ae212763bd9d158a4','{"hasNext":false,"items":[{"author":{"account":{"login":"colintrator-a11y","providerType":"User"},"email":"colintrator-a11y@users.noreply.github.com","name":"colintrator-a11y"},"authoredDate":"2026-09-07T04:32:04Z","committedDate":"2026-09-07T04:32:04Z","committer":{"account":{"login":"colintrator-a11y","providerType":"User"},"email":"colintrator-a11y@users.noreply.github.com","name":"colintrator-a11y"},"observedAt":"2026-10-09T00:33:32.131Z","repositoryId":1359746093,"sha":"0b3cb48d14d9960bf0d86961c94951572d2d1094"}],"observedAt":"2026-10-09T00:33:32.131Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/302381041?v=4","events_url":"https://api.github.com/users/colintrator-a11y/events{/privacy}","followers_url":"https://api.github.com/users/colintrator-a11y/followers","following_url":"https://api.github.com/users/colintrator-a11y/following{/other_user}","gists_url":"https://api.github.com/users/colintrator-a11y/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/colintrator-a11y","id":302381041,"login":"colintrator-a11y","node_id":"U_kgDOEgX38Q","organizations_url":"https://api.github.com/users/colintrator-a11y/orgs","received_events_url":"https://api.github.com/users/colintrator-a11y/received_events","repos_url":"https://api.github.com/users/colintrator-a11y/repos","site_admin":false,"starred_url":"https://api.github.com/users/colintrator-a11y/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/colintrator-a11y/subscriptions","type":"User","url":"https://api.github.com/users/colintrator-a11y","user_view_type":"public"},"comments_url":"https://api.github.com/repos/colintrator-a11y/workana-slack-bot/commits/0b3cb48d14d9960bf0d86961c94951572d2d1094/comments","commit":{"author":{"date":"2026-09-07T04:32:04Z","email":"colintrator-a11y@users.noreply.github.com","name":"colintrator-a11y"},"comment_count":0,"committer":{"date":"2026-09-07T04:32:04Z","email":"colintrator-a11y@users.noreply.github.com","name":"colintrator-a11y"},"message":"Add Workana to Slack job notification bot\n\nWatches the public Workana job board and posts new projects to Slack.\n\nFetching: Workana renders the board client-side and sits behind Cloudflare,\nwhich rejects ordinary HTTP clients. The listings are nonetheless present in\nthe first response, embedded as JSON in a Vue :results-initials attribute, so\nthe bot reads that with a browser-grade TLS fingerprint (curl_cffi) rather\nthan driving a headless browser. A DOM parser and an optional Playwright\nfetcher remain as fallbacks.\n\nFeatures:\n- Posts each new job as a Block Kit message with budget, skills, client,\n  publication time, client history, bid counts and category\n- SQLite de-duplication keyed on the job slug, so restarts never re-post\n- Freshness window, keyword filters, category and language selection\n- Optional Workana session cookie for full client names and a larger board\n- Randomised poll delay with adaptive back-off when Workana pushes back\n- pm2 process definition, plus a systemd alternative\n\nTested with 116 offline checks against saved board fixtures, covering both\nparse paths so a markup change fails loudly.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"7ed8b3b6295d3886ca9929ae981288877cc6d6eb","url":"https://api.github.com/repos/colintrator-a11y/workana-slack-bot/git/trees/7ed8b3b6295d3886ca9929ae981288877cc6d6eb"},"url":"https://api.github.com/repos/colintrator-a11y/workana-slack-bot/git/commits/0b3cb48d14d9960bf0d86961c94951572d2d1094","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/302381041?v=4","events_url":"https://api.github.com/users/colintrator-a11y/events{/privacy}","followers_url":"https://api.github.com/users/colintrator-a11y/followers","following_url":"https://api.github.com/users/colintrator-a11y/following{/other_user}","gists_url":"https://api.github.com/users/colintrator-a11y/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/colintrator-a11y","id":302381041,"login":"colintrator-a11y","node_id":"U_kgDOEgX38Q","organizations_url":"https://api.github.com/users/colintrator-a11y/orgs","received_events_url":"https://api.github.com/users/colintrator-a11y/received_events","repos_url":"https://api.github.com/users/colintrator-a11y/repos","site_admin":false,"starred_url":"https://api.github.com/users/colintrator-a11y/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/colintrator-a11y/subscriptions","type":"User","url":"https://api.github.com/users/colintrator-a11y","user_view_type":"public"},"html_url":"https://github.com/colintrator-a11y/workana-slack-bot/commit/0b3cb48d14d9960bf0d86961c94951572d2d1094","node_id":"C_kwDOUQwULdoAKDBiM2NiNDhkMTRkOTk2MGJmMGQ4Njk2MWM5NDk1MTU3MmQyZDEwOTQ","parents":[],"sha":"0b3cb48d14d9960bf0d86961c94951572d2d1094","url":"https://api.github.com/repos/colintrator-a11y/workana-slack-bot/commits/0b3cb48d14d9960bf0d86961c94951572d2d1094"}],"requestUrl":"https://api.github.com/repos/colintrator-a11y/workana-slack-bot/commits?per_page=100&page=1&sha=0b3cb48d14d9960bf0d86961c94951572d2d1094&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A02%3A36.034Z"}');
