lied on, not its field\nnames.","tree":{"sha":"5d1724d9f417913640570e14a2efb9ee516b596e","url":"https://api.github.com/repos/francogarayokk/FE_case_study_innoscripta/git/trees/5d1724d9f417913640570e14a2efb9ee516b596e"},"url":"https://api.github.com/repos/francogarayokk/FE_case_study_innoscripta/git/commits/20e7ac2ac8a55bd3d471bc08082c298bf97105c0","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/66415085?v=4","events_url":"https://api.github.com/users/francogarayokk/events{/privacy}","followers_url":"https://api.github.com/users/francogarayokk/followers","following_url":"https://api.github.com/users/francogarayokk/following{/other_user}","gists_url":"https://api.github.com/users/francogarayokk/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/francogarayokk","id":66415085,"login":"francogarayokk","node_id":"MDQ6VXNlcjY2NDE1MDg1","organizations_url":"https://api.github.com/users/francogarayokk/orgs","received_events_url":"https://api.github.com/users/francogarayokk/received_events","repos_url":"https://api.github.com/users/francogarayokk/repos","site_admin":false,"starred_url":"https://api.github.com/users/francogarayokk/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/francogarayokk/subscriptions","type":"User","url":"https://api.github.com/users/francogarayokk","user_view_type":"public"},"html_url":"https://github.com/francogarayokk/FE_case_study_innoscripta/commit/20e7ac2ac8a55bd3d471bc08082c298bf97105c0","node_id":"C_kwDOUQ5bWNoAKDIwZTdhYzJhYzhhNTViZDNkNDcxYmMwODA4MmMyOThiZjk3MTA1YzA","parents":[{"html_url":"https://github.com/francogarayokk/FE_case_study_innoscripta/commit/fd8d8be709f05e10273ef41cb60db1c51ab6e24e","sha":"fd8d8be709f05e10273ef41cb60db1c51ab6e24e","url":"https://api.github.com/repos/francogarayokk/FE_case_study_innoscripta/commits/fd8d8be709f05e10273ef41cb60db1c51ab6e24e"}],"sha":"20e7a